CREATE TABLE IF NOT EXISTS schema_version(version int PRIMARY KEY);
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, currency text NOT NULL DEFAULT 'USD');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL);
CREATE TABLE memberships(org_id uuid REFERENCES organizations, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('admin','manager','viewer')), PRIMARY KEY(org_id,user_id));
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES organizations, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','manager','viewer')), accepted_at timestamptz, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days');
CREATE TABLE login_tokens(hash text PRIMARY KEY, email text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE sessions(hash text PRIMARY KEY, user_id uuid REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE auth_limits(key text PRIMARY KEY, hits int NOT NULL, resets_at timestamptz NOT NULL);
CREATE TABLE resources(org_id uuid REFERENCES organizations, id uuid DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name)>0), daily_hours numeric(5,2) NOT NULL DEFAULT 8 CHECK(daily_hours>0 AND daily_hours<=24), PRIMARY KEY(org_id,id));
CREATE TABLE projects(org_id uuid REFERENCES organizations, id uuid DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name)>0), budget_cents bigint NOT NULL DEFAULT 0 CHECK(budget_cents>=0), PRIMARY KEY(org_id,id));
CREATE TABLE sprints(org_id uuid REFERENCES organizations,id uuid DEFAULT gen_random_uuid(),name text NOT NULL,start_date date NOT NULL,end_date date NOT NULL CHECK(end_date>=start_date),PRIMARY KEY(org_id,id));
CREATE TABLE tasks(org_id uuid REFERENCES organizations,id uuid DEFAULT gen_random_uuid(),project_id uuid NOT NULL,jira_key text NOT NULL,title text NOT NULL,estimate_hours numeric(8,2) NOT NULL CHECK(estimate_hours>=0),start_date date NOT NULL,target_date date NOT NULL CHECK(target_date>=start_date),status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','hold','done')),primary_owner_id uuid NOT NULL,sprint_id uuid,version int NOT NULL DEFAULT 1,PRIMARY KEY(org_id,id),UNIQUE(org_id,jira_key),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,primary_owner_id) REFERENCES resources(org_id,id),FOREIGN KEY(org_id,sprint_id) REFERENCES sprints(org_id,id));
CREATE TABLE allocations(org_id uuid,id uuid DEFAULT gen_random_uuid(),task_id uuid NOT NULL,resource_id uuid NOT NULL,day date NOT NULL,hours numeric(5,2) NOT NULL CHECK(hours>0 AND hours<=24),released_at timestamptz,release_reason text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,task_id) REFERENCES tasks(org_id,id),FOREIGN KEY(org_id,resource_id) REFERENCES resources(org_id,id));
CREATE TABLE rates(org_id uuid,id uuid DEFAULT gen_random_uuid(),resource_id uuid NOT NULL,effective_from date NOT NULL,hourly_cents bigint NOT NULL CHECK(hourly_cents>=0),PRIMARY KEY(org_id,id),UNIQUE(org_id,resource_id,effective_from),FOREIGN KEY(org_id,resource_id) REFERENCES resources(org_id,id));
CREATE TABLE worklogs(org_id uuid,id uuid DEFAULT gen_random_uuid(),task_id uuid NOT NULL,resource_id uuid NOT NULL,day date NOT NULL,hours numeric(5,2) NOT NULL CHECK(hours>0 AND hours<=24),hourly_cents bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,task_id) REFERENCES tasks(org_id,id),FOREIGN KEY(org_id,resource_id) REFERENCES resources(org_id,id));
CREATE TABLE audit_events(org_id uuid,id uuid DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES users,entity_id uuid NOT NULL,action text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['resources','projects','sprints','tasks','allocations','rates','worklogs','audit_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format($policy$CREATE POLICY tenant_scope ON %I USING (org_id = nullif(current_setting('app.tenant',true),'')::uuid) WITH CHECK (org_id = nullif(current_setting('app.tenant',true),'')::uuid)$policy$,t); END LOOP; END $$;
CREATE FUNCTION preserve_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Historical records are append-only'; END $$;
CREATE TRIGGER immutable_rates BEFORE UPDATE OR DELETE ON rates FOR EACH ROW EXECUTE FUNCTION preserve_history();
CREATE TRIGGER immutable_worklogs BEFORE UPDATE OR DELETE ON worklogs FOR EACH ROW EXECUTE FUNCTION preserve_history();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION preserve_history();
INSERT INTO schema_version VALUES(1);
